  reports:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',
  registry:'<path d="M8 3v5M16 3v5M5 8h14v5a7 7 0 0 1-14 0zM12 20v2"/>',
